"""QPU server: executes function calls from QPU libraries (generated by qpu_dll.py) on the quantum machine.

A host program linked against a generated library (libNAME_qpu.so) calls the library's functions as
ordinary C functions. The library sends each call here over a Unix socket; the server runs the
function on the quantum machine (the simulator of this repository), checks it against the CPU
reference, and sends back the return value, the output buffers and the text the function printed.

The library starts the server by itself when none is running, so usually you never start it by hand:

    python3 qpu_server.py                      # foreground, default socket
    python3 qpu_server.py --socket /tmp/q.sock --idle-exit 600 -v

Where it listens (--socket, else $QPU_SERVER, else the platform default):
  a Unix socket path                         Linux default: /tmp/cpu-qpu-<uid>.sock
  an endpoint file ending in .txt: TCP       Windows default: %LOCALAPPDATA%\\cpu-qpu\\qpu-server.txt
In TCP mode the server listens on 127.0.0.1 (a free port) and writes "127.0.0.1 <port> <token>" to
the endpoint file, readable only by the user; every connection must start with "AUTH <token>".

Protocol (text lines; numbers are decimal):

    LOAD <sha256> <nbytes>\\n<object file bytes>         ->  OK  |  ERR <message>
    CALL <sha256> <function> <backend> <width> <nargs> <arg>...\\n
    BUF <arg index> <in|out|inout> <count> <value>...\\n   (one line per pointer argument)
    END\\n
                                                        ->  STATUS <status>
                                                            RESULT <value>
                                                            CYCLES <n>
                                                            BUF <arg index> <count> <value>...   (out / inout)
                                                            OUT <nbytes>\\n<text>
                                                            MSG <nbytes>\\n<text>
                                                            END
status: ok | inexact (a value left the W-bit model; result may differ from the CPU) |
        mismatch (QPU differs from the CPU) | error (did not run: unsupported instruction, no halt,
        bad call) | unknown-lib (send LOAD, then repeat the call)
backend: sim (quantum machine, checked against the CPU) | cpu (CPU reference only)
"""
import argparse, hashlib, os, secrets, socket, socketserver, sys, threading, time

ROOT = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, ROOT)
import cpu_qpu
from qcpu import isa as isas

CACHE = os.path.join(os.environ.get("XDG_CACHE_HOME", os.path.expanduser("~/.cache")), "cpu-qpu", "libs")
LOCK = threading.Lock()            # one call at a time: the simulator and the circuit cache are shared
LIBS = {}                          # sha256 -> object file path
MACHINES = {}                      # circuit cache (see cpu_qpu.execute)
STATE = dict(last=time.time(), calls=0, verbose=False)


def default_socket():
    if os.environ.get("QPU_SERVER"):
        return os.environ["QPU_SERVER"]
    if os.name == "nt":
        return os.path.join(os.environ.get("LOCALAPPDATA", os.path.expanduser("~")), "cpu-qpu", "qpu-server.txt")
    return f"/tmp/cpu-qpu-{os.getuid()}.sock"


def is_tcp(endpoint):
    return endpoint.endswith(".txt")


def running(endpoint):
    """Is a server already answering at this endpoint?"""
    try:
        if is_tcp(endpoint):
            host, port, token = open(endpoint).read().split()
            s = socket.create_connection((host, int(port)), timeout=2)
            s.sendall(f"AUTH {token}\n".encode())
            ok = s.makefile("rb").readline().strip() == b"OK"
        else:
            s = socket.socket(socket.AF_UNIX)
            s.settimeout(2)
            s.connect(endpoint)
            ok = True
        s.close()
        return ok
    except (OSError, ValueError):
        return False


def log(*a):
    if STATE["verbose"]:
        print(time.strftime("%H:%M:%S"), *a, file=sys.stderr, flush=True)


def call(sha, fn, backend, width, args, bufs):
    """Run fn(args) from library sha. bufs: {arg index: (direction, [values])}. Returns a reply dict."""
    path = LIBS.get(sha)
    if path is None:
        cand = os.path.join(CACHE, sha + ".o")
        if not os.path.exists(cand):
            return dict(status="unknown-lib")
        LIBS[sha] = path = cand
    cfg = cpu_qpu.load_config(os.path.join(ROOT, "config.json"))
    cfg["register_width"] = width
    # pointer arguments: buffers one after another in the user cells, argument = '&first cell'
    arg_strs, mem, where = [], [], {}
    for i, a in enumerate(args):
        if i in bufs:
            d, vals = bufs[i]
            where[i] = (len(mem), len(vals))
            arg_strs.append(f"&{len(mem)}")
            mem += vals if d != "out" else [0] * len(vals)
        else:
            arg_strs.append(str(a))
    try:
        isa = isas.get(isas.detect(path))
        r = cpu_qpu.execute(path, isa, cfg, fn, arg_strs, mem, machine_cache=MACHINES, round_steps=True,
                            qpu=backend != "cpu")
    except SystemExit as e:                    # execute reports user errors the way the command line does
        return dict(status="error", msg=str(e.code).removeprefix("error: "))
    except Exception as e:                     # noqa: BLE001 -- report, keep serving
        return dict(status="error", msg=f"{type(e).__name__}: {e}")
    ref = r["ref"]
    if r["stop"] is not None:
        return dict(status="error", msg=ref["error"] or "the quantum machine did not complete the run")
    # r["ok"]: QPU == CPU (None for the cpu backend); r["exact"]: no model-check issue
    if r["ok"] is False and r["exact"]:
        status, msg = "mismatch", r["report"]["verdict"]          # never expected: the tests look for this
    elif not r["exact"]:
        status, msg = "inexact", "; ".join(ref["issues"][:3])     # explained by the W-bit model
    else:
        status, msg = "ok", ""
    base = r["user_off"] // 4
    out = {i: r["mem"][base + o: base + o + n] for i, (o, n) in where.items() if bufs[i][0] != "in"}
    return dict(status=status, result=r["ret"], cycles=ref["steps"], bufs=out, out=r["qtext"] or "", msg=msg)


class Handler(socketserver.StreamRequestHandler):
    def handle(self):
        f = self.rfile
        token = getattr(self.server, "token", None)
        if token:                                    # TCP: the first line must carry the token
            first = f.readline().decode(errors="replace").split()
            if first[:1] != ["AUTH"] or len(first) != 2 or not secrets.compare_digest(first[1], token):
                return
            self.wfile.write(b"OK\n"); self.wfile.flush()
        while True:
            line = f.readline()
            if not line:
                return
            STATE["last"] = time.time()
            parts = line.decode().split()
            if not parts:
                continue
            if parts[0] == "LOAD":
                sha, n = parts[1], int(parts[2])
                data = f.read(n)
                if hashlib.sha256(data).hexdigest() != sha:
                    self.wfile.write(b"ERR checksum mismatch\n"); continue
                os.makedirs(CACHE, exist_ok=True)
                path = os.path.join(CACHE, sha + ".o")
                with open(path + ".tmp", "wb") as o:
                    o.write(data)
                os.replace(path + ".tmp", path)
                LIBS[sha] = path
                log("load", sha[:12], n, "bytes")
                self.wfile.write(b"OK\n"); self.wfile.flush()
            elif parts[0] == "CALL":
                sha, fn, backend, width, nargs = parts[1], parts[2], parts[3], int(parts[4]), int(parts[5])
                args = [int(x) for x in parts[6:6 + nargs]]
                bufs = {}
                while True:
                    b = f.readline().decode().split()
                    if not b or b[0] == "END":
                        break
                    bufs[int(b[1])] = (b[2], [int(x) for x in b[4:4 + int(b[3])]])
                t = time.time()
                with LOCK:
                    rep = call(sha, fn, backend, width, args, bufs)
                    STATE["calls"] += 1
                log("call", f"{fn}{tuple(args)}", backend, f"W={width}", "->", rep["status"], rep.get("result"),
                    f"{time.time() - t:.2f}s", rep.get("msg", ""))
                w = [f"STATUS {rep['status']}"]
                if "result" in rep:
                    w += [f"RESULT {rep['result']}", f"CYCLES {rep['cycles']}"]
                    w += [f"BUF {i} {len(v)} " + " ".join(map(str, v)) for i, v in rep["bufs"].items()]
                txt = rep.get("out", "").encode()
                msg = rep.get("msg", "").encode()
                self.wfile.write(("\n".join(w) + f"\nOUT {len(txt)}\n").encode() + txt + f"MSG {len(msg)}\n".encode() + msg + b"END\n")
                self.wfile.flush()
            elif parts[0] == "PING":
                self.wfile.write(b"OK\n"); self.wfile.flush()
            else:
                self.wfile.write(b"ERR unknown request\n"); self.wfile.flush()


class TCPServer(socketserver.ThreadingMixIn, socketserver.TCPServer):
    daemon_threads = True


if hasattr(socketserver, "UnixStreamServer"):
    class UnixServer(socketserver.ThreadingMixIn, socketserver.UnixStreamServer):
        daemon_threads = True


def main():
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--socket", default=default_socket())
    ap.add_argument("--idle-exit", type=float, default=0, help="exit after this many seconds without a request (0 = never)")
    ap.add_argument("-v", "--verbose", action="store_true", help="log every call to stderr")
    a = ap.parse_args()
    STATE["verbose"] = a.verbose
    if os.path.exists(a.socket):
        if running(a.socket):
            sys.exit(f"a QPU server is already listening at {a.socket}")
        os.unlink(a.socket)                    # left over from a server that is gone
    if is_tcp(a.socket):
        srv = TCPServer(("127.0.0.1", 0), Handler)
        srv.token = secrets.token_hex(16)
        os.makedirs(os.path.dirname(os.path.abspath(a.socket)), exist_ok=True)
        tmp = a.socket + ".tmp"
        fd = os.open(tmp, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
        os.write(fd, f"127.0.0.1 {srv.server_address[1]} {srv.token}\n".encode())
        os.close(fd)
        os.replace(tmp, a.socket)
        log("listening on 127.0.0.1 port", srv.server_address[1], "endpoint file", a.socket)
    else:
        if not hasattr(socketserver, "UnixStreamServer"):
            sys.exit("Unix sockets are not available here: give an endpoint file ending in .txt (TCP)")
        srv = UnixServer(a.socket, Handler)
        os.chmod(a.socket, 0o600)
        log("listening on", a.socket)
    if a.idle_exit:
        def watch():
            while time.time() - STATE["last"] < a.idle_exit:
                time.sleep(1)
            log("idle, exiting")
            srv.shutdown()
        threading.Thread(target=watch, daemon=True).start()
    try:
        srv.serve_forever()
    finally:
        srv.server_close()
        if os.path.exists(a.socket):
            os.unlink(a.socket)


if __name__ == "__main__":
    main()
